public void testValidAndInvalidFileSystems() {
    FileSystem fs = mock(FileSystem.class);
    /* Valid FileSystem schemes */
    doReturn("s3a").when(fs).getScheme();
    assertTrue(isBlobStorageFileSystem(conf, fs));
