    assertFalse(isBlobStorageFileSystem(conf, fs));
    doReturn("").when(fs).getScheme();
    assertFalse(isBlobStorageFileSystem(conf, fs));
    assertFalse(isBlobStorageFileSystem(conf, null));
}

