    amReporter.start();
    // register two tasks of same query but different am
    int am1Port = 123;
    int am2Port = 456;
    String am1Location = "am1";
    String am2Location = "am2";
    String umbilicalUser = "user";
    QueryIdentifier queryId = new QueryIdentifier("app", 0);
    amReporter.registerTask(am1Location, am1Port, umbilicalUser, null, queryId, mock(TezTaskAttemptID.class), false);
    amReporter.registerTask(am2Location, am2Port, umbilicalUser, null, queryId, mock(TezTaskAttemptID.class), false);
