@Before
public void setup() throws Exception {
    String[] strIntervals = HiveConf.getTrimmedStringsVar(daemonConf, HiveConf.ConfVars.LLAP_DAEMON_TASK_PREEMPTION_METRICS_INTERVALS);
    List<Integer> intervalList = new ArrayList<>();
    if (strIntervals != null) {
        for (String strInterval : strIntervals) {
            intervalList.add(Integer.valueOf(strInterval));
        }
    }
    amReporter = mock(AMReporter.class);
    serverSocket = new InetSocketAddress("localhost", 0);
    srvAddress.set(serverSocket);
    this.metrics = LlapDaemonExecutorMetrics.create("ContinerRunerTests", MetricsUtils.getUUID(), numExecutors, Ints.toArray(intervalList));
    for (int i = 0; i < numLocalDirs; i++) {
        File f = new File(testWorkDir, "localDir");
        f.mkdirs();
        localDirs[i] = f.getAbsolutePath();
    }
    String waitQueueSchedulerClassName = HiveConf.getVar(daemonConf, HiveConf.ConfVars.LLAP_DAEMON_WAIT_QUEUE_COMPARATOR_CLASS_NAME);
    queryTracker = new QueryTracker(daemonConf, localDirs, daemonId.getClusterString());
    executorService = new TaskExecutorService(numExecutors, waitQueueSize, waitQueueSchedulerClassName, enablePreemption, Thread.currentThread().getContextClassLoader(), metrics, null);
    shufflePort.set(HiveConf.getIntVar(daemonConf, HiveConf.ConfVars.LLAP_DAEMON_RPC_PORT));
    containerRunner = new ContainerRunnerImpl(daemonConf, numExecutors, this.shufflePort, srvAddress, executorMemoryPerInstance, metrics, amReporter, queryTracker, executorService, daemonId, LlapUgiFactoryFactory.createFsUgiFactory(daemonConf), socketFactory);
    ShuffleHandler.initializeAndStart(daemonConf);
    executorService.init(daemonConf);
    executorService.start();
    queryTracker.init(daemonConf);
    queryTracker.start();
    containerRunner.init(daemonConf);
    containerRunner.start();
}

@Test(timeout = 10000)
public void testSimpleCall() throws ServiceException, IOException {
    LlapDaemonConfiguration daemonConf = new LlapDaemonConfiguration();
    int numHandlers = HiveConf.getIntVar(daemonConf, ConfVars.LLAP_DAEMON_RPC_NUM_HANDLERS);
    ContainerRunner containerRunnerMock = mock(ContainerRunner.class);
    LlapProtocolServerImpl server = new LlapProtocolServerImpl(null, numHandlers, containerRunnerMock, new AtomicReference<InetSocketAddress>(), new AtomicReference<InetSocketAddress>(), 0, 0, null);
    when(containerRunnerMock.submitWork(any(SubmitWorkRequestProto.class))).thenReturn(SubmitWorkResponseProto.newBuilder().setSubmissionState(SubmissionStateProto.ACCEPTED).build());
    try {
        server.init(new Configuration());
        server.start();
        InetSocketAddress serverAddr = server.getBindAddress();
        LlapProtocolBlockingPB client = new LlapProtocolClientImpl(new Configuration(), serverAddr.getHostName(), serverAddr.getPort(), null, null, null);
        SubmitWorkResponseProto responseProto = client.submitWork(null, SubmitWorkRequestProto.newBuilder().setAmHost("amhost").setAmPort(2000).build());
        assertEquals(responseProto.getSubmissionState().name(), SubmissionStateProto.ACCEPTED.name());
    } finally {
        server.stop();
    }
}

